resultDetails.input:
{
  "message": "J’ai chargé le skill d’empreinte, mais je n’ai pas reçu le fichier audio à traiter. Le texte « /certificat-truetone » ne précise pas de fichier. Pour calculer l’empreinte sans écrire le fichier sur le disque et enregistrer le dépôt, indique le fichier à traiter et les renseignements suivants. Vous pouvez aussi joindre directement le fichier si l’interface le permet.",
  "requestedSchema": {
    "properties": {
      "fichier": {
        "type": "string",
        "title": "Fichier à déposer",
        "description": "Chemin complet du fichier sur cet ordinateur, ou dites que vous allez le joindre."
      },
      "artiste": {
        "type": "string",
        "title": "Artiste"
      },
      "titre": {
        "type": "string",
        "title": "Titre du morceau"
      },
      "ia_utilisee": {
        "type": "string",
        "title": "IA utilisée ?",
        "enum": [
          "non",
          "oui"
        ],
        "default": "non"
      },
      "etapes_ia": {
        "type": "string",
        "title": "Étapes IA",
        "description": "Étapes concernées, ou « aucune »."
      },
      "commentaire": {
        "type": "string",
        "title": "Commentaire",
        "description": "Facultatif."
      }
    }
  }
}
